fn main() {
    let grid = [[1, 2, 3], [4, 99, 6], [7, 8, 9]];
    let mut found = None;
    'rows: for (r, row) in grid.iter().enumerate() {
        for (c, value) in row.iter().enumerate() {
            if *value == 99 {
                found = Some((r, c));
                break 'rows;
            }
        }
    }
    println!("99 found at {found:?}");
}

fn main() {
    let mut n = 27u64;
    let mut steps = 0;
    while n != 1 {
        n = if n % 2 == 0 { n / 2 } else { 3 * n + 1 };
        steps += 1;
    }
    println!("27 reaches 1 after {steps} steps");
}

